SelectionManager.proxyMethod("locationMapper.findContainerAndOffsetFromLocation")
SelectionManager.proxyMethod("locationMapper.findNodeAndOffsetFromLocation")
SelectionManager.proxyMethod("pointMapper.createDOMRangeFromPoint")
SelectionManager.proxyMethod("pointMapper.getClientRectsForDOMRange")

import BasicObject from "trix/core/basic_object"

export default class SelectionChangeObserver extends BasicObject {
  constructor() {
    super(...arguments)
    this.update = this.update.bind(this)
    this.selectionManagers = []
  }

  start() {
    if (!this.started) {
      this.started = true
      document.addEventListener("selectionchange", this.update, true)
    }
  }

  stop() {
    if (this.started) {
      this.started = false
      return document.removeEventListener("selectionchange", this.update, true)
    }
  }

  registerSelectionManager(selectionManager) {
    if (!this.selectionManagers.includes(selectionManager)) {
      this.selectionManagers.push(selectionManager)
      return this.start()
    }
  }

  unregisterSelectionManager(selectionManager) {
    this.selectionManagers = this.selectionManagers.filter((sm) => sm !== selectionManager)
    if (this.selectionManagers.length === 0) {
      return this.stop()
    }
  }

  notifySelectionManagersOfSelectionChange() {
    return this.selectionManagers.map((selectionManager) => selectionManager.selectionDidChange())
  }

  update() {
    this.notifySelectionManagersOfSelectionChange()
  }

  reset() {
    this.update()
  }
}

export const selectionChangeObserver = new SelectionChangeObserver()

export const getDOMSelection = function() {
  const selection = window.getSelection()
  if (selection.rangeCount > 0) {
    return selection
  }
}

export const getDOMRange = function() {
  const domRange = getDOMSelection()?.getRangeAt(0)
  if (domRange) {
    if (!domRangeIsPrivate(domRange)) {
      return domRange
    }
  }
}

export const setDOMRange = function(domRange) {
  const selection = window.getSelection()
  selection.removeAllRanges()
  selection.addRange(domRange)
  return selectionChangeObserver.update()
}

// In Firefox, clicking certain <input> elements changes the selection to a
// private element used to draw its UI. Attempting to access properties of those
// elements throws an error.
// https://bugzilla.mozilla.org/show_bug.cgi?id=208427
const domRangeIsPrivate = (domRange) => nodeIsPrivate(domRange.startContainer) || nodeIsPrivate(domRange.endContainer)

const nodeIsPrivate = (node) => !Object.getPrototypeOf(node)

package org.fxmisc.richtext.demo;

import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.paint.Color;
import javafx.stage.Stage;
import javafx.util.Duration;
import org.fxmisc.richtext.CaretNode;
import org.fxmisc.richtext.InlineCssTextArea;
import org.fxmisc.richtext.Selection;
import org.fxmisc.richtext.SelectionImpl;

public class MultiCaretAndSelectionDemo extends Application {

    private InlineCssTextArea area;

    public static void main(String[] args) {
        launch(args);
    }

    @Override
    public void start(Stage primaryStage) {
        // initialize area with some lines of text
        String alphabet = "abcdefghijklmnopqrstuvwxyz";
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 10; i++) {
            sb.append(i).append(" :").append(alphabet).append("\n");
        }
        area = new InlineCssTextArea(sb.toString());

        setupRTFXSpecificCSSShapes();

        addExtraCaret();

        addExtraSelection();

        // select some other range with the regular caret/selection before showing area
        area.selectRange(2, 0, 2, 4);

        primaryStage.setScene(new Scene(area, 400, 400));
        primaryStage.show();

        // request focus so carets blink
        area.requestFocus();
    }

    private void addExtraCaret() {
        CaretNode extraCaret = new CaretNode("another caret", area);
        if (!area.addCaret(extraCaret)) {
            throw new IllegalStateException("caret was not added to area");
        }
        extraCaret.moveTo(3, 8);

        // since the CSS properties are re-set when it applies the CSS from files
        // remove the style class so that properties set below are not overridden by CSS
        extraCaret.getStyleClass().remove("caret");

        extraCaret.setStrokeWidth(10.0);
        extraCaret.setStroke(Color.BROWN);
        extraCaret.setBlinkRate(Duration.millis(200));
    }

    private void addExtraSelection() {
        Selection<String, String, String> extraSelection = new SelectionImpl<>("another selection", area,
                path -> {
                    // make rendered selection path look like a yellow highlighter
                    path.setStrokeWidth(0);
                    path.setFill(Color.YELLOW);
                }
        );
        if (!area.addSelection(extraSelection)) {
            throw new IllegalStateException("selection was not added to area");
        }
        // select something so it is visible
        extraSelection.selectRange(7, 2, 7, 8);
    }

    /**
     * Shows that RTFX-specific-CSS shapes are laid out in correct order, so that
     * selection and text and caret appears on top of them when made/moved
     */
    private void setupRTFXSpecificCSSShapes() {
        String background = "-rtfx-background-color: red; ";
        String underline = "-rtfx-underline-color: blue; " +
                "-rtfx-underline-width: 2.0;";
        String border = "-rtfx-border-stroke-color: green; " +
                "-rtfx-border-stroke-width: 3.0;";

        // set all of them at once on a give line to insure they display properly
        area.setStyle(0, background + underline + border);

        // set each one over a given segment
        area.setStyle(1, 0, 3, background);
        area.setStyle(1, 4, 7, underline);
        area.setStyle(1, 8, 11, border);
    }
}

package org.fxmisc.richtext;

import org.fxmisc.richtext.model.PlainTextChange;

import java.util.List;

class CaretPositionChange {
    /**
     * Goes through the list of change and update the caret position accordingly
     * @param position the current caret position
     * @param list the list of changes
     * @return the new caret position
     */
    public int apply(int position, List<PlainTextChange> list) {
        for (PlainTextChange plainTextChange : list) {
            int netLength = plainTextChange.getNetLength();
            if (netLength != 0) {
                int indexOfChange = plainTextChange.getPosition();
                // in case of a replacement: "hello there" -> "hi."
                int endOfChange = indexOfChange + Math.abs(netLength);

                    /*
                        "->" means add (positive) netLength to position
                        "<-" means add (negative) netLength to position
                        "x" means don't update position

                        "+c" means caret was included in the deleted portion of content
                        "-c" means caret was not included in the deleted portion of content
                        Before/At/After means indexOfChange "<" / "==" / ">" position

                               |   Before +c   | Before -c | At | After
                        -------+---------------+-----------+----+------
                        Add    |      N/A      |    ->     | -> | x
                        Delete | indexOfChange |    <-     | x  | x
                     */
                if (indexOfChange == position && netLength > 0) {
                    position = position + netLength;
                } else if (indexOfChange < position) {
                    position = position < endOfChange ? indexOfChange : position + netLength;
                }
            }
        }
        return position;
    }
}

import { expect } from 'chai';
import jsdomGlobal from 'jsdom-global';
import Highlighter from '../src/index';

describe('Native selection lifecycle', function () {
    this.timeout(50000);

    let cleanup: () => void;

    beforeEach(() => {
        cleanup = jsdomGlobal();
        document.body.innerHTML = '<p>start <a href="#">link</a> middle <i>italic</i> end</p>';
    });

    afterEach(() => {
        cleanup();
    });

    const selectAcrossTextNodes = () => {
        const $p = document.querySelector('p');
        const range = document.createRange();

        range.setStart($p.firstChild, 2);
        range.setEnd($p.lastChild, 3);

        const selection = window.getSelection();

        selection.removeAllRanges();
        selection.addRange(range);

        return { range, text: range.toString() };
    };

    it('should keep the native selection untouched by default', () => {
        const { range } = selectAcrossTextNodes();
        const highlighter = new Highlighter();

        expect(highlighter.fromRange(range)).not.to.be.null;
        expect(window.getSelection().rangeCount).to.equal(1);
    });

    it('should drop the native selection when asked to clear it', () => {
        const { range, text } = selectAcrossTextNodes();
        const highlighter = new Highlighter();

        const source = highlighter.fromRange(range, { selection: 'clear' });

        expect(source.text).to.equal(text);
        expect(window.getSelection().isCollapsed).to.be.true;
    });

    it('should select the created wrappers when asked to restore it', () => {
        const { range, text } = selectAcrossTextNodes();
        const highlighter = new Highlighter();

        const source = highlighter.fromRange(range, { selection: 'restore' });

        expect(source.text).to.equal(text);
        expect(window.getSelection().toString()).to.equal(text);
    });

    it('should not leave a truncated selection in the automatic mode', () => {
        const highlighter = new Highlighter();

        highlighter.run();

        const { text } = selectAcrossTextNodes();

        document.body.dispatchEvent(new MouseEvent('mouseup', { view: window, bubbles: true, cancelable: true }));

        expect(
            highlighter
                .getDoms()
                .map($n => $n.textContent)
                .join(''),
        ).to.equal(text);
        expect(window.getSelection().isCollapsed).to.be.true;
    });
});
